<?php

declare(strict_types=1);

namespace App\Domain\Products;

use App\Domain\Audit\AuditService;
use App\Infrastructure\Database\ConnectionProvider;
use App\Infrastructure\Repositories\ProductAttributeRepository;
use App\Infrastructure\Repositories\ProductFamilyRepository;
use App\Infrastructure\Repositories\ProductVariantRepository;
use PDOException;

final class ProductVariantService
{
    public function __construct(private readonly ConnectionProvider $connection, private readonly ProductFamilyRepository $families, private readonly ProductAttributeRepository $attributes, private readonly ProductVariantRepository $variants, private readonly AuditService $audit) { }
    public function members(int $family): array { return $this->variants->members($family); }
    public function values(string $product): array { return $this->variants->values($product); }
    public function link(int $family,string $product,array $rawValues,int $actor,bool $default=false): void { $pdo=$this->connection->pdo();$this->validateProduct($product);$familyRow=$this->families->find($family);if($familyRow===null||$familyRow['activo']!=1||$familyRow['eliminado_en']!==null){throw new ProductVariantException(['family'=>'La familia no está activa.']);}$values=$this->validateValues($family,$rawValues);$hash=$this->hash($values);$pdo->beginTransaction();try{$existing=$this->variants->member($family,$product);if($existing!==null&&$existing['eliminado_en']===null){throw new ProductVariantException(['product'=>'El producto ya pertenece a una familia.']);}if($default){$this->variants->clearDefault($family,$actor);}if($existing!==null){$this->variants->reactivate((int)$existing['membresia_id'],$actor,$default,$hash);}else{$this->variants->insertMember(['family'=>$family,'product'=>$product,'default'=>$default,'hash'=>$hash,'actor'=>$actor]);}$this->variants->replaceValues($product,$values,$actor);$this->audit->recordRequired('productos.variantes.vincular',$actor,['entidad'=>'producto_familia_miembro','entidad_id'=>$product,'version_contrato'=>1,'modulo'=>'productos','producto_id'=>$product,'subrecurso'=>'variante','familia_id'=>$family]);$pdo->commit();}catch(ProductVariantException $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}catch(PDOException $e){if($pdo->inTransaction())$pdo->rollBack();throw new ProductVariantException(['product'=>'No fue posible vincular la variante.'],$e->getMessage());}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
    public function unlink(string $product,int $actor): void { $m=$this->variants->activeMembership($product);if($m===null){throw new ProductVariantException(['product'=>'El producto no tiene familia activa.']);}$pdo=$this->connection->pdo();$pdo->beginTransaction();try{$this->variants->softDelete((int)$m['membresia_id'],$actor);$this->audit->recordRequired('productos.variantes.desvincular',$actor,['entidad'=>'producto_familia_miembro','entidad_id'=>$product,'version_contrato'=>1,'modulo'=>'productos','producto_id'=>$product,'subrecurso'=>'variante','familia_id'=>(int)$m['familia_id']]);$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
    public function updateValues(string $product,array $rawValues,int $actor): void { $m=$this->variants->activeMembership($product);if($m===null){throw new ProductVariantException(['product'=>'El producto no tiene familia activa.']);}$values=$this->validateValues((int)$m['familia_id'],$rawValues);$hash=$this->hash($values);$pdo=$this->connection->pdo();$pdo->beginTransaction();try{$this->variants->replaceValues($product,$values,$actor);$this->variants->reactivate((int)$m['membresia_id'],$actor,(bool)$m['es_predeterminada'],$hash);$this->audit->recordRequired('productos.variantes.atributos.actualizar',$actor,['entidad'=>'producto_familia_miembro','entidad_id'=>$product,'version_contrato'=>1,'modulo'=>'productos','producto_id'=>$product,'subrecurso'=>'variante']);$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
    public function setDefault(string $product,int $actor): void { $m=$this->variants->activeMembership($product);if($m===null){throw new ProductVariantException(['product'=>'El producto no tiene familia activa.']);}$pdo=$this->connection->pdo();$pdo->beginTransaction();try{$this->variants->clearDefault((int)$m['familia_id'],$actor);$this->variants->setDefault((int)$m['membresia_id'],$actor);$this->audit->recordRequired('productos.variantes.predeterminada',$actor,['entidad'=>'producto_familia_miembro','entidad_id'=>$product,'version_contrato'=>1,'modulo'=>'productos','producto_id'=>$product,'subrecurso'=>'variante']);$pdo->commit();}catch(\Throwable $e){if($pdo->inTransaction())$pdo->rollBack();throw $e;}}
    private function validateProduct(string $product): void { $s=$this->connection->pdo()->prepare('SELECT id_producto FROM productos WHERE id_producto=:id AND activo=1 AND eliminado_en IS NULL');$s->execute(['id'=>$product]);if($s->fetchColumn()===false){throw new ProductVariantException(['product'=>'El producto debe existir y estar activo.']);}}
    private function validateValues(int $family,array $raw): array { $allowed=$this->families->allowedAttributes($family);$map=[];foreach($allowed as $a){$map[(int)$a['atributo_id']]=$a;}$seen=[];$values=[];foreach($raw as $row){$attribute=(int)($row['attribute']??0);$value=(int)($row['value']??0);if(isset($seen[$attribute])||!isset($map[$attribute]))throw new ProductVariantException(['attributes'=>'El atributo no está permitido o está repetido.']);$v=$this->attributes->value($value);if($v===null||(int)$v['atributo_id']!==$attribute||(int)$v['activo']!==1||$v['eliminado_en']!==null)throw new ProductVariantException(['attributes'=>'El valor no pertenece al atributo.']);$seen[$attribute]=true;$values[]=['attribute'=>$attribute,'value'=>$value];}foreach($map as $id=>$a){if((int)$a['obligatorio']===1&&!isset($seen[$id]))throw new ProductVariantException(['attributes'=>'Falta un atributo obligatorio.']);}usort($values,static fn($a,$b)=>$a['attribute']<=>$b['attribute']);return $values;}
    private function hash(array $values): string { $parts=[];foreach($values as $v){$parts[]=$v['attribute'].':'.$v['value'];}return hash('sha256',implode('|',$parts),true); }
}
